101	// =============================================================================
102	// SvgGenerator class
103	// =============================================================================
104	
105	export class SvgGenerator {
106	  private readonly width: number;
107	  private readonly height: number;
108	  private readonly colorScheme: 'default' | 'colorblind';
109	
110	  constructor(options?: SvgOptions) {
111	    this.width = options?.width ?? 800;
112	    this.height = options?.height ?? 500;
113	    this.colorScheme = options?.colorScheme ?? 'default';
114	  }
115	
116	  // ---------------------------------------------------------------------------
117	  // Topic bar chart
118	  // ---------------------------------------------------------------------------
119	
120	  generateTopicBarChart(
121	    topicFrequency: Record<string, number>,
122	    date: string,
123	    topN = 10,
124	  ): string {
125	    log.info(`Generating topic bar chart for ${date} (topN=${topN})`);
126	
127	    const entries = Object.entries(topicFrequency)
128	      .sort((a, b) => b[1] - a[1])
129	      .slice(0, Math.max(1, topN)); // At least try to show 1
130	
131	    if (entries.length === 0) {
132	      // Empty state
133	      return this.emptySvg(`AI 话题热度 — ${date}`, '暂无话题数据', date);
134	    }
135	
136	    const maxVal = entries[0][1];
137	    const w = this.width;
138	    const h = this.height;
139	
140	    const barH = 30;
141	    const barGap = 5;
142	    const barAreaTop = 70;
143	    const barAreaBottom = 430;
144	    const maxBars = Math.min(entries.length, Math.floor((barAreaBottom - barAreaTop) / (barH + barGap)));
145	    const limited = entries.slice(0, maxBars);
146	
147	    const labelX = 200;
148	    const barStartX = 210;
149	    const maxBarWidth = 440;
150	    const valueX = 660;
151	
152	    const bars: string[] = [];
153	    const gridLines: string[] = [];
154	    const labels: string[] = [];
155	    const values: string[] = [];
156	
157	    // Grid lines (0%, 25%, 50%, 75%, 100%)
158	    for (const pct of [0, 0.25, 0.5, 0.75, 1]) {
159	      const gx = barStartX + maxBarWidth * pct;
160	      gridLines.push(`  <line class="grid" x1="${gx.toFixed(1)}" y1="${barAreaTop - 10}" x2="${gx.toFixed(1)}" y2="${barAreaTop + limited.length * (barH + barGap)}" />`);
161	    }
162	
163	    limited.forEach(([topic, count], i) => {
164	      const y = barAreaTop + i * (barH + barGap);
165	      const barWidth = maxVal > 0 ? (count / maxVal) * maxBarWidth : 0;
166	
167	      const colorIndex = this.colorScheme === 'colorblind'
168	        ? i % BARS_COLORBLIND.length
169	        : i % BARS_DEFAULT.length;
170	      const color = this.colorScheme === 'colorblind'
171	        ? BARS_COLORBLIND[colorIndex]
172	        : (i < 1 ? BARS_DEFAULT[0] : BARS_DEFAULT[Math.min(colorIndex, BARS_DEFAULT.length - 1)]);
173	
174	      // If colorblind, add pattern
175	      let rectExtra = '';
176	      if (this.colorScheme === 'colorblind') {
177	        rectExtra = ` fill="url(#cbBar${i})"`;
178	        // Add pattern definition (will be hoisted)
179	      } else {
180	        rectExtra = ` fill="${color}"`;
181	      }
182	
183	      labels.push(`  <text class="label" x="${labelX}" y="${y + barH / 2 + 4}" text-anchor="end">${truncate(topic, 15)}</text>`);
184	      bars.push(`  <rect role="bar" x="${barStartX}" y="${y}" width="${barWidth.toFixed(1)}" height="${barH}" rx="4"${rectExtra} />`);
185	      values.push(`  <text class="value" x="${valueX}" y="${y + barH / 2 + 4}">${count}</text>`);
186	    });
187	
188	    // Add pattern defs for colorblind
189	    let defs = '';
190	    if (this.colorScheme === 'colorblind') {
191	      const patterns = limited.map((_, i) => {
192	        const colorIndex = i % BARS_COLORBLIND.length;
193	        const color = BARS_COLORBLIND[colorIndex];
194	        return `  <pattern id="cbBar${i}" patternUnits="userSpaceOnUse" width="8" height="8">
195	    <rect width="8" height="8" fill="${color}" />
196	    <rect x="${i % 2 * 4}" y="${i % 2 * 4}" width="4" height="4" fill="#ffffff" opacity="0.4" />
197	  </pattern>`;
198	      });
199	      defs = `<defs>\n${patterns.join('\n')}\n  </defs>\n`;
200	    }
201	
202	    const svgContent = [
203	      defs,
204	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">AI 话题热度 Top-${limited.length} — ${date}</text>`,
205	      gridLines.join('\n'),
206	      labels.join('\n'),
207	      bars.join('\n'),
208	      values.join('\n'),
209	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
210	    ].join('\n');
211	
212	    return wrapSvg(svgContent, w, h);
213	  }
214	
215	  // ---------------------------------------------------------------------------
216	  // Sentiment donut chart
217	  // ---------------------------------------------------------------------------
218	
219	  generateSentimentDonut(
220	    sentimentDistribution: Record<string, number>,
221	    date: string,
222	  ): string {
223	    log.info(`Generating sentiment donut for ${date}`);
224	
225	    const entries = Object.entries(sentimentDistribution).filter(([, v]) => v > 0);
226	    const total = entries.reduce((s, [, v]) => s + v, 0);
227	
228	    const w = 600;
229	    const h = 500;
230	    const cx = 300;
231	    const cy = 250;
232	    const outerR = 120;
233	    const innerR = 60;
234	
235	    if (total === 0) {
236	      return this.emptySvg(`情感分布 — ${date}`, '暂无情感数据', date);
237	    }
238	
239	    const colors = this.colorScheme === 'colorblind'
240	      ? SENTIMENT_COLORS_COLORBLIND
241	      : SENTIMENT_COLORS_DEFAULT;
242	
243	    // Sort entries for consistent rendering: positive, neutral, negative
244	    const sorted = ['positive', 'neutral', 'negative']
245	      .filter((k) => entries.some(([key]) => key === k))
246	      .map((k) => [k, entries.find(([key]) => key === k)![1]] as [string, number]);
247	
248	    const paths: string[] = [];
249	    const legendItems: string[] = [];
250	
251	    // Start from the top (-90 degrees)
252	    let currentAngle = -90;
253	
254	    sorted.forEach(([key, value], idx) => {
255	      const pct = value / total;
256	      const sweepDeg = pct * 360;
257	      const endAngle = currentAngle + sweepDeg;
258	
259	      const color = colors[key] || '#6B7280';
260	
261	      // Add pattern defs for colorblind
262	      if (this.colorScheme === 'colorblind') {
263	        // Use texture via pattern
264	        paths.push(donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle));
265	        paths.push(`  <path d="${donutArcPath(cx, cy, innerR - 2, outerR + 2, currentAngle, endAngle)}" fill="none" stroke="#333" stroke-width="1" />`);
266	      } else {
267	        paths.push(`  <path d="${donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle)}" fill="${color}" />`);
268	      }
269	
270	      // Legend
271	      const legendY = 150 + idx * 30;
272	      legendItems.push(`  <rect x="430" y="${legendY}" width="12" height="12" rx="2" fill="${color}" />`);
273	      legendItems.push(`  <text class="label" x="450" y="${legendY + 10}">${SENTIMENT_LABELS[key] || key} (${value})</text>`);
274	
275	      currentAngle = endAngle;
276	    });
277	
278	    const svgContent = [
279	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">情感分布 — ${date}</text>`,
280	      paths.join('\n'),
281	      `  <text class="value" x="${cx}" y="${cy - 8}" text-anchor="middle" font-size="24" font-weight="bold" fill="#111827">N=${total}</text>`,
282	      `  <text class="note" x="${cx}" y="${cy + 12}" text-anchor="middle" font-size="12">条</text>`,
283	      legendItems.join('\n'),
284	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
285	    ].join('\n');
286	
287	    return wrapSvg(svgContent, w, h);
288	  }
289	
290	  // ---------------------------------------------------------------------------
291	  // Trend radar chart
292	  // ---------------------------------------------------------------------------
293	
294	  generateTrendRadar(trends: TrendAnalysis, date: string): string {
295	    log.info(`Generating trend radar for ${date}`);
296	
297	    const w = 600;
298	    const h = 600;
299	    const cx = 300;
300	    const cy = 300;
301	    const axisLen = 200;
302	
303	    type TrendDimensionKey = 'technology' | 'application' | 'policy' | 'capital';
304	
305	    interface AxisDef {
306	      key: TrendDimensionKey;
307	      label: string;
308	      angleDeg: number; // clockwise from positive x-axis
309	    }
310	
311	    const axes: AxisDef[] = [
312	      { key: 'technology', label: '技术', angleDeg: -90 },
313	      { key: 'application', label: '应用', angleDeg: 0 },
314	      { key: 'policy', label: '政策', angleDeg: 90 },
315	      { key: 'capital', label: '资本', angleDeg: 180 },
316	    ];
317	
318	    // Helper to get data point on an axis
319	    const getPoint = (angleDeg: number, ratio: number) =>
320	      polarPoint(cx, cy, axisLen * ratio, angleDeg);
321	
322	    // Grid polygons (0.25, 0.5, 0.75, 1.0)
323	    const gridPolygons: string[] = [];
324	    for (const ratio of [0.25, 0.5, 0.75, 1.0]) {
325	      const pts = axes.map((a) => {
326	        const p = getPoint(a.angleDeg, ratio);
327	        return `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
328	      });
329	      gridPolygons.push(`  <polygon class="grid" points="${pts.join(' ')}" fill="none" />`);
330	    }
331	
332	    // Axes lines from center to edge
333	    const axisLines: string[] = [];
334	    const axisLabels: string[] = [];
335	    axes.forEach((a) => {
336	      const tip = getPoint(a.angleDeg, 1.0);
337	      axisLines.push(`  <line class="axis" x1="${cx}" y1="${cy}" x2="${tip.x.toFixed(1)}" y2="${tip.y.toFixed(1)}" />`);
338	
339	      // Label at tip + offset
340	      const offset = 20;
341	      let lx = tip.x;
342	      let ly = tip.y;
343	      let anchor = 'middle';
344	      if (a.angleDeg === -90) { ly = tip.y - offset; anchor = 'middle'; }
345	      else if (a.angleDeg === 0) { lx = tip.x + offset; anchor = 'start'; }
346	      else if (a.angleDeg === 90) { ly = tip.y + offset; anchor = 'middle'; }
347	      else if (a.angleDeg === 180) { lx = tip.x - offset; anchor = 'end'; }
348	
349	      axisLabels.push(`  <text class="label" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="${anchor}" font-weight="bold" font-size="14">${a.label}</text>`);
350	
351	      // Ref labels at 0.25 intervals
352	      for (const r of [0.25, 0.5, 0.75]) {
353	        const rp = getPoint(a.angleDeg, r);
354	        refLabels.push(`  <text class="ref-text" x="${rp.x.toFixed(1)}" y="${rp.y.toFixed(1) + 3}" text-anchor="${a.angleDeg === 180 ? 'end' : a.angleDeg === 0 ? 'start' : 'middle'}">${r.toFixed(2)}</text>`);
355	      }
356	    });
357	
358	    // Data polygon
359	    const dataPoints = axes.map((a) => {
360	      const dim = trends[a.key];
361	      const conf = dim?.confidence ?? 0;
362	      const p = getPoint(a.angleDeg, conf);
363	      return `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
364	    });
365	
366	    // Data value labels at each axis
367	    const dataLabels: string[] = [];
368	    axes.forEach((a) => {
369	      const dim = trends[a.key];
370	      const conf = dim?.confidence ?? 0;
371	      const p = getPoint(a.angleDeg, conf);
372	      const off = 12;
373	      const dx = a.angleDeg === 180 ? -off : a.angleDeg === 0 ? off : 0;
374	      const dy = a.angleDeg === -90 ? -off : a.angleDeg === 90 ? off : 0;
375	      const anchor = a.angleDeg === 180 ? 'end' : a.angleDeg === 0 ? 'start' : 'middle';
376	      dataLabels.push(`  <text class="value" x="${(p.x + dx).toFixed(1)}" y="${(p.y + dy).toFixed(1)}" text-anchor="${anchor}" font-size="13" font-weight="bold" fill="#3B82F6">${conf.toFixed(2)}</text>`);
377	    });
378	
379	    const svgContent = [
380	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">四维趋势雷达 — ${date}</text>`,
381	      gridPolygons.join('\n'),
382	      axisLines.join('\n'),
383	      refLabels.join('\n'),
384	      axisLabels.join('\n'),
385	      `  <polygon points="${dataPoints.join(' ')}" fill="rgba(59, 130, 246, 0.2)" stroke="#3B82F6" stroke-width="2" />`,
386	      dataLabels.join('\n'),
387	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
388	    ].join('\n');
389	
390	    return wrapSvg(svgContent, w, h);
391	  }
392	
393	  // ---------------------------------------------------------------------------
394	  // Empty state helper
395	  // ---------------------------------------------------------------------------
396	
397	  private emptySvg(title: string, message: string, date?: string): string {
398	    const w = this.width;
399	    const h = this.height;
400	    const dateStr = date ?? '';
401	    const svgContent = [
402	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">${title}</text>`,
403	      `  <text class="value" x="${w / 2}" y="${h / 2}" text-anchor="middle">${message}</text>`,
404	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine${dateStr ? ` — ${dateStr}` : ''}</text>`,
405	    ].join('\n');
406	    return wrapSvg(svgContent, w, h);
407	  }
408	}
