76	describe('SvgGenerator.generateTopicBarChart', () => {
77	  const gen = new SvgGenerator();
78	
79	  test('returns a valid SVG string starting with <svg and ending with </svg>', () => {
80	    const svg = gen.generateTopicBarChart({ '大语言模型': 8, 'AI监管': 5 }, '2026-06-01');
81	    expect(svg.startsWith('<svg')).toBe(true);
82	    expect(svg.endsWith('</svg>')).toBe(true);
83	  });
84	
85	  test('SVG contains xmlns and viewBox attributes', () => {
86	    const svg = gen.generateTopicBarChart({ '大语言模型': 8 }, '2026-06-01');
87	    expect(svg).toContain('xmlns="http://www.w3.org/2000/svg"');
88	    expect(svg).toContain('viewBox="');
89	  });
90	
91	  test('bar chart title contains the date', () => {
92	    const svg = gen.generateTopicBarChart({ '大语言模型': 8 }, '2026-06-01');
93	    expect(svg).toContain('2026-06-01');
94	  });
95	
96	  test('bar chart contains data source note', () => {
97	    const svg = gen.generateTopicBarChart({ '大语言模型': 8 }, '2026-06-01');
98	    expect(svg).toContain('数据来源');
99	  });
100	
101	  test('bars are sorted in descending order (first bar wider than second)', () => {
102	    const svg = gen.generateTopicBarChart({ '话题A': 10, '话题B': 5, '话题C': 2 }, '2026-06-01');
103	    // The first bar should have a larger width value than the second
104	    const barWidths: number[] = [];
