  legendItems.push(`  <rect x="430" y="${legendY}" width="12" height="12" rx="2" fill="${color}" />`);
  legendItems.push(`  <text class="label" x="450" y="${legendY + 10}">${SENTIMENT_LABELS[key] || key} (${value})</text>`);
});

